import io, json, os, time, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
MODEL = 'qwen2.5:14b'
TIMEOUT = 1500
LANE = 'cpu'
CPU_THREADS = 4      # CEO 10% CPU margin law (O-20260913-2215)
GENERATE_URL = 'http://localhost:11434/api/generate'
MATERIAL = 'MC-20261013-REACT-v16 static card (cards.json + render output + e4-material.md)'
prompt = '你是一名刷公众号图文/信息流的普通读者，看到下面这张静态速报卡《城市速报 016》\n（1080×1080 方图·黑底；左上角小字「[AIGC·AI 生成内容]」；顶部大标题「城市速报 016」）。\n图上写着：\n「今日热点 · 知乎热榜 2026-10-13」；\n「中文在线称，中国55%的token消耗指向AI短剧，」；\n「如何看待这一现象？」——这两行是知乎热榜第 1 条热点标题原文；\n「侠气轴：「酒馆里故事多，今夜谁又成了英雄？」」；\n「求新轴：「夜深人不静，创意不停歇」」；\n「烟火轴：「熬了大半夜的锅，汤汁才够味儿」」——这三行是虚构硅基城市居民的三句反应；\n「字幕君信条：「字幕慢半帧，都是对说话人的辜负。」」——这是虚构城市里一位字幕君的信条。\n图内底部声明行「热点转述自知乎热榜·反应与信条皆取自虚构城市档案」。\n背景：硅基城市是一家由 AI 全自主运转的公司集团（只有一个人类老板，其余成员全是 AI）。\n「城市速报」系列是集团旗下媒体公司出品的热点反应卡——把当天真实热榜话题原样转述，\n再用虚构城市居民的台词和信条做出反应，所以底部声明行写明热点是现实转述、反应是虚构档案。\n本卡的热点是：知乎热榜 2026-10-13 第 1 条（835 万热度）——中文在线称中国 55% 的 token 消耗指向 AI 短剧，\n大家都在讨论这个现象说明什么。城市反应三句分别对应热点的三个面：\n故事多英雄夜夜翻新=短剧故事工厂的会心句；创意不停歇=深夜赶工造内容大军的镜像；熬锅够味=token 是炉火功夫才出味的城市正身；\n字幕君信条收束=AI 短剧生产链上管字幕轴的内容工种本人，对量产时代内容质量之问的工艺答卷。\n请回答三个问题，每题一段，直说不委婉：\n1) 刷到这张卡你会停下来看吗？会保存或转发给朋友吗？打几分（0-10）？为什么？\n2) 有没有一眼假、空洞套话的地方？有的话扣几分、指出原句？\n3) 最弱的一项是什么？'

result = {'ts': time.strftime('%Y-%m-%d %H:%M:%S'), 'model': MODEL,
          'material': MATERIAL, 'lane': LANE}
payload = json.dumps({'model': MODEL, 'prompt': prompt, 'stream': False,
                      'options': {'num_gpu': 0,
                                  'num_thread': CPU_THREADS}}).encode('utf-8')
request = urllib.request.Request(GENERATE_URL, data=payload,
                                 headers={'Content-Type': 'application/json'})
try:
    with urllib.request.urlopen(request, timeout=TIMEOUT) as resp:
        body = json.loads(resp.read().decode('utf-8', 'replace'))
    result['verdict'] = (body.get('response') or '').strip() or \
        'EMPTY-RESPONSE'
except Exception as exc:
    text = '%s: %s' % (type(exc).__name__, exc)
    if 'timed out' in text.lower() or 'timeout' in text.lower():
        result['verdict'] = 'TIMEOUT-%ds' % TIMEOUT
    else:
        print('TRANSPORT-ERROR %s' % text, flush=True)
        raise SystemExit(3)
io.open(os.path.join(HERE, 'e4-result.json'), 'w', encoding='utf-8').write(
    json.dumps(result, ensure_ascii=False, indent=2))
print('DONE' if not result['verdict'].startswith('TIMEOUT') else 'TIMEOUT')
